<?php declare(strict_types=1);require_once __DIR__.'/../../../bootstrap/app.php';use App\Services\Auth;use App\Services\DispatchService;use App\Support\Url;Auth::requirePermission('TRIP_VIEW_DRIVER');$rows=DispatchService::driverTrips((int)Auth::user()['id']);$pageTitle='My Trips';require BASE_PATH.'/app/Views/layout/header.php';?><h1>My trips</h1><div class="card"><?php foreach($rows as$r):?><p><a href="<?=h(Url::to('driver/trips/view.php?id='.$r['trip_id']))?>"><?=h($r['trip_ref'].' · '.$r['origin_city'].' → '.$r['destination_city'].' · '.$r['current_status'])?></a></p><?php endforeach;if(!$rows):?><p>No trips.</p><?php endif;?></div><?php require BASE_PATH.'/app/Views/layout/footer.php';
